def _history_repeat_counts(history: list[int], maxlen: int) -> np.ndarray:
    counts = np.zeros(maxlen, dtype=np.float32)
    seen = defaultdict(int)
    start = max(0, len(history) - maxlen)
    offset = max(0, maxlen - len(history))
    for index, item in enumerate(history):
        if item != 0:
            if index >= start:
                counts[offset + index - start] = seen[item]
            seen[item] += 1
    return counts


