def input_embeddings(self, seq: torch.Tensor, repeat_counts: torch.Tensor) -> torch.Tensor:
    scale = 1.0 + 0.1 * torch.tanh(torch.log1p(repeat_counts.float()))
    scale = torch.where(seq.ne(0), scale, torch.ones_like(scale))
    emb = self.item_emb(seq)
    return self.dropout(emb * scale.to(emb.dtype).unsqueeze(-1))

def encode(self, seq: torch.Tensor, repeat_counts: torch.Tensor) -> torch.Tensor:
    emb = self.input_embeddings(seq, repeat_counts)

